"servers": {
"zoho-crm-data-insights": {
"url": "https://zoho-crm-data-insights-60065097786.zohomcp.in/mcp/d17dfe13292e0414a929516bb8f8e797/message",
"type": "http"
}
}
}
{
"servers": {
"zoho-crm-data-operations": {
